from pyspark.sql.utils import AnalysisException
from pyspark.sql.functions import col

def read_csv_safe(path, table_name, expected_columns=None):
    try:
        df = spark.read.csv(
            path,
            header=True,
            inferSchema=True,
            mode="PERMISSIVE",
            columnNameOfCorruptRecord="corrupt_record"
        )

        # Vérification 1 : fichier vide
        nb_lignes = df.count()
        if nb_lignes == 0:
            return None, False, f"⚠️ [{table_name}] Fichier vide : {path}"

        # Vérification 2 : colonnes attendues présentes
        if expected_columns:
            missing_cols = set(expected_columns) - set(df.columns)
            if missing_cols:
                return None, False, f"⚠️ [{table_name}] Colonnes manquantes : {missing_cols}"

        # Vérification 3 : isoler les lignes corrompues
        if "corrupt_record" in df.columns:
            lignes_corrompues = df.filter(col("corrupt_record").isNotNull())
            nb_corrompues = lignes_corrompues.count()
            if nb_corrompues > 0:
                lignes_corrompues.write.mode("overwrite").parquet(
                    f"abfss://raw@adlsbougrine.dfs.core.windows.net/quarantine/{table_name}_corrupt/"
                )
                print(f"⚠️ [{table_name}] {nb_corrompues} lignes corrompues isolées en quarantaine")
            df = df.filter(col("corrupt_record").isNull()).drop("corrupt_record")

        return df, True, f"✅ [{table_name}] Lecture réussie : {nb_lignes} lignes"

    except AnalysisException as e:
        return None, False, f"❌ [{table_name}] Fichier introuvable ou illisible : {str(e)}"
    except Exception as e:
        return None, False, f"❌ [{table_name}] Erreur inattendue : {str(e)}"

