from pyspark.sql.functions import regexp_replace, col, when, concat, lit, substring, to_date, year, current_date, coalesce

df_customers_clean = df_customers_clean.withColumn(
    "birth_date_clean", regexp_replace(col("birth_date"), r"[/.]", "-")
).withColumn(
    "birth_date_clean",
    when(
        col("birth_date_clean").rlike(r'^\d{8}$'),
        concat(
            substring(col("birth_date_clean"), 1, 4), lit("-"),
            substring(col("birth_date_clean"), 5, 2), lit("-"),
            substring(col("birth_date_clean"), 7, 2)
        )
    ).when(
        col("birth_date_clean").rlike(r'^\d{2}-\d{2}-\d{4}$'), 
        concat(
            substring(col("birth_date_clean"), 7, 4), lit("-"),
            substring(col("birth_date_clean"), 1, 2), lit("-"),  
            substring(col("birth_date_clean"), 4, 2)             
        )
    ).otherwise(col("birth_date_clean"))
).withColumn(
    "birth_date", to_date(col("birth_date_clean"), "yyyy-MM-dd")
).withColumn(
    "age", year(current_date()) - year(col("birth_date"))
).drop("birth_date_clean")

